    Stack<AbstractType> stack = ...; // Initialize stack if not already available
    for (int i = 0; i < descriptor.length(); i++) {
        char ch = descriptor.charAt(i);
        if (ch == ')') {
            // End of method descriptor, no more types to pop
            break;
        } else if (ch == 'L') {
            // Class descriptor
            int semiColonIndex = descriptor.indexOf(';', i);
            stack.pop();
