public OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (start == null || stop == null) {
        throw new IllegalArgumentException("Start and stop nodes cannot be null");
    }

    OuterFaceCirculator circulator = new OuterFaceCirculator(start, dir);
    Node currentNode = start;

    while (currentNode != stop) {
        if (predicate.test(currentNode)) {
            return circulator;
        }
        currentNode = circulator.next();
    }

