        throw new IllegalArgumentException("Invalid start index");
    }
    if (len < 0 || index + len > str.length()) {
        throw new IllegalArgumentException("Invalid length");
    }

    int size = 0;
    for (int i = 0; i < len; i++) {
        char c = str.charAt(index + i);
        if ((c & 0x7F) == c) {
            size += 1;
        } else if ((c & 0xE0) == 0xC0) {
